<script setup lang="ts">
const {request,can}=useAdminApi();const tab=ref('center'),loading=ref(false),busy=ref(false),error=ref(''),success=ref('');
const center=reactive({name:'',phone:'',email:'',address:'',website:'',logo_url:'',timezone:'Asia/Tehran'}),seo=reactive({title:'',description:'',canonical_base:'',og_image:''});
const weekdays=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'];const hours=ref<any[]>([]),holidays=ref<any[]>([]),holidayForm=reactive({holiday_date:'',title:'',is_open:false,opens_at:'',closes_at:''});
const settingsFields=[['site_name','نام سایت'],['phone','تلفن عمومی'],['instagram','اینستاگرام'],['telegram','تلگرام'],['about','معرفی کوتاه']];const generic=reactive<Record<string,string>>({});
function message(e:any){return Object.values(e?.data?.errors||{}).flat().join(' · ')||e?.data?.message||'عملیات انجام نشد.';}
async function load(){loading.value=true;error.value='';try{const [c,h,d,s,g]:any[]=await Promise.all([request('/admin/settings/center-profile'),request('/admin/settings/working-hours'),request('/admin/settings/holidays?per_page=100'),request('/admin/settings/seo'),request('/admin/settings')]);Object.assign(center,c.data||{});hours.value=h.data||[];holidays.value=d.data?.data||d.data||[];Object.assign(seo,s.data||{});for(const [key] of settingsFields)generic[key]=String(g[key]??'');}catch(e:any){error.value=message(e);}finally{loading.value=false;}}
async function saveCenter(){busy.value=true;error.value='';try{await request('/admin/settings/center-profile',{method:'PUT',body:{...center}});success.value='مشخصات مرکز ذخیره شد.';}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function saveSeo(){busy.value=true;error.value='';try{await request('/admin/settings/seo',{method:'PUT',body:{...seo}});success.value='پیش‌فرض‌های SEO ذخیره شد.';}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function saveHours(){busy.value=true;error.value='';try{for(const row of hours.value){await request('/admin/settings/working-hours',{method:'PUT',body:{weekday:row.weekday,is_open:!!row.is_open,opens_at:row.is_open?row.opens_at:null,closes_at:row.is_open?row.closes_at:null}});}success.value='ساعات مرکز ذخیره شد.';await load();}catch(e:any){error.value=message(e);await load();}finally{busy.value=false;}}
async function addHoliday(){if(busy.value)return;busy.value=true;error.value='';try{await request('/admin/settings/holidays',{method:'POST',body:{...holidayForm}});Object.assign(holidayForm,{holiday_date:'',title:'',is_open:false,opens_at:'',closes_at:''});success.value='تعطیلی مرکز ثبت شد.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function removeHoliday(item:any){if(!confirm(`تعطیلی ${item.title||item.holiday_date} حذف شود؟`))return;busy.value=true;try{await request(`/admin/settings/holidays/${item.id}`,{method:'DELETE'});success.value='تعطیلی حذف شد.';await load();}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
async function saveGeneric(){busy.value=true;error.value='';try{for(const [key] of settingsFields)await request('/admin/settings',{method:'PUT',body:{key,value:generic[key]||''}});success.value='تنظیمات عمومی ذخیره شد.';}catch(e:any){error.value=message(e);}finally{busy.value=false;}}
onMounted(load);
</script>
<template><main dir="rtl" class="admin-page"><header class="admin-page__header"><div><div class="admin-eyebrow">پیکربندی مرکز</div><h1>تنظیمات</h1><p>هر بخش از قرارداد مشخص backend خوانده و ذخیره می‌شود.</p></div><v-btn variant="tonal" :loading="loading" @click="load">به‌روزرسانی</v-btn></header><v-alert v-if="error" type="error" variant="tonal" class="mb-3">{{error}}</v-alert><v-alert v-if="success" type="success" variant="tonal" class="mb-3">{{success}}</v-alert><v-progress-linear v-if="loading" indeterminate class="mb-3"/><v-tabs v-model="tab" class="mb-4"><v-tab value="center">مشخصات مرکز</v-tab><v-tab value="hours">ساعات کاری</v-tab><v-tab value="holidays">تعطیلات</v-tab><v-tab value="seo">SEO</v-tab><v-tab value="generic">تنظیمات عمومی</v-tab></v-tabs>
<v-card v-if="tab==='center'" class="pa-5"><v-row><v-col cols="12" md="6"><v-text-field v-model="center.name" label="نام مرکز"/></v-col><v-col cols="12" md="6"><v-text-field v-model="center.phone" label="تلفن"/></v-col><v-col cols="12" md="6"><v-text-field v-model="center.email" type="email" label="ایمیل"/></v-col><v-col cols="12" md="6"><v-text-field v-model="center.website" label="وب‌سایت"/></v-col><v-col cols="12"><v-textarea v-model="center.address" label="نشانی"/></v-col><v-col cols="12" md="6"><v-text-field v-model="center.logo_url" label="نشانی لوگو"/></v-col><v-col cols="12" md="6"><v-text-field v-model="center.timezone" label="منطقه زمانی" readonly/></v-col></v-row><v-btn color="primary" :loading="busy" @click="saveCenter">ذخیره مشخصات</v-btn></v-card>
<v-card v-else-if="tab==='hours'" class="pa-5"><v-alert type="warning" variant="tonal" class="mb-3">اگر تغییر ساعات با رزروهای آینده ناسازگار باشد، backend ذخیره را رد می‌کند. ذخیره برای هر روز جداگانه انجام می‌شود؛ بعد از خطا داده را دوباره بارگذاری کنید.</v-alert><v-row v-for="hour in hours" :key="hour.weekday" align="center"><v-col cols="12" md="3"><strong>{{weekdays[hour.weekday]}}</strong></v-col><v-col cols="12" md="2"><v-switch v-model="hour.is_open" label="باز" hide-details/></v-col><v-col cols="6" md="3"><v-text-field v-model="hour.opens_at" type="time" label="از" :disabled="!hour.is_open"/></v-col><v-col cols="6" md="3"><v-text-field v-model="hour.closes_at" type="time" label="تا" :disabled="!hour.is_open"/></v-col></v-row><v-btn color="primary" :loading="busy" @click="saveHours">ذخیره ساعات</v-btn></v-card>
<v-card v-else-if="tab==='holidays'" class="pa-5"><h2 class="mb-3">افزودن تعطیلی</h2><v-row><v-col cols="12" md="3"><v-text-field v-model="holidayForm.holiday_date" type="date" label="تاریخ"/></v-col><v-col cols="12" md="3"><v-text-field v-model="holidayForm.title" label="عنوان"/></v-col><v-col cols="12" md="2"><v-switch v-model="holidayForm.is_open" label="مرکز باز است"/></v-col><v-col v-if="holidayForm.is_open" cols="6" md="2"><v-text-field v-model="holidayForm.opens_at" type="time" label="از"/></v-col><v-col v-if="holidayForm.is_open" cols="6" md="2"><v-text-field v-model="holidayForm.closes_at" type="time" label="تا"/></v-col></v-row><v-btn class="mb-5" color="primary" :disabled="!holidayForm.holiday_date|| (holidayForm.is_open&&(!holidayForm.opens_at||!holidayForm.closes_at))" :loading="busy" @click="addHoliday">ثبت تعطیلی</v-btn><v-table><thead><tr><th>تاریخ</th><th>عنوان</th><th>وضعیت</th><th></th></tr></thead><tbody><tr v-for="h in holidays" :key="h.id"><td>{{h.holiday_date}}</td><td>{{h.title||'—'}}</td><td>{{h.is_open?`باز ${h.opens_at}–${h.closes_at}`:'تعطیل'}}</td><td><v-btn color="error" size="small" @click="removeHoliday(h)">حذف</v-btn></td></tr><tr v-if="!holidays.length"><td colspan="4">تعطیلی‌ای ثبت نشده است.</td></tr></tbody></v-table></v-card>
<v-card v-else-if="tab==='seo'" class="pa-5"><v-text-field v-model="seo.title" label="عنوان پیش‌فرض SEO"/><v-textarea v-model="seo.description" label="توضیحات پیش‌فرض"/><v-text-field v-model="seo.canonical_base" label="دامنه canonical"/><v-text-field v-model="seo.og_image" label="تصویر Open Graph"/><v-btn color="primary" :loading="busy" @click="saveSeo">ذخیره SEO</v-btn></v-card>
<v-card v-else class="pa-5"><v-alert type="info" variant="tonal" class="mb-3">این‌ها کلیدهای عمومی مجاز در API هستند؛ کلیدهای شامل secret/token از backend بازگردانده نمی‌شوند.</v-alert><v-text-field v-for="[key,label] in settingsFields" :key="key" v-model="generic[key]" :label="label"/><v-btn color="primary" :loading="busy" @click="saveGeneric">ذخیره تنظیمات عمومی</v-btn></v-card></main></template>
